// Plazos de la revisión (T-0040): a las 24 h sin decisión un recordatorio (una vez por propuesta) y a las 48 h la pieza pasa a stalled.
// El plazo cuenta desde el último review_send exitoso: reenviar la propuesta (editar, regenerar, reabrir) lo reinicia
const REMIND_H = 24, STALL_H = 48;
const base = `${$env.SUPABASE_URL}/rest/v1`;
const key = $env.SUPABASE_SERVICE_ROLE_KEY;
const headers = { apikey: key, Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' };
const req = (method, path, { qs, body, prefer } = {}) => this.helpers.httpRequest({ method, url: `${base}/${path}`, qs, body, json: true, timeout: 30000,
  headers: prefer ? { ...headers, Prefer: prefer } : headers });
const tg = (method, body) => this.helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/${method}`, body, json: true, timeout: 30000 });
const out = { checked: 0, reminded: 0, stalled: 0, errors: 0 };
const logError = async (itemId, error_type, err) => {
  out.errors++;
  try { await req('POST', 'error_log', { prefer: 'return=minimal', body: { workflow: '22-revisar-plazos', content_item_id: itemId, error_type, error_message: String(err?.message ?? err).replace(/bot\d+:[A-Za-z0-9_-]+/g, 'bot***').slice(0, 500) } }); } catch (e) { /* sin más recursos */ }
};

const items = await req('GET', 'content_items', { qs: { select: 'id,title_youtube,caption_instagram', status: 'eq.ready_for_review', limit: '200' } });
out.checked = items.length;
if (items.length === 0) return [{ json: out }];
const sends = await req('GET', 'pipeline_steps', { qs: { select: 'content_item_id,attempt,finished_at', step: 'eq.review_send', status: 'eq.succeeded',
  content_item_id: `in.(${items.map((i) => i.id).join(',')})`, order: 'finished_at.desc', limit: '1000' } });
const last = new Map();
for (const s of sends) if (!last.has(s.content_item_id)) last.set(s.content_item_id, s);

const chat_id = $env.TELEGRAM_APPROVER_CHAT_ID;
for (const item of items) {
  const send = last.get(item.id);
  if (!send) continue;
  const ageH = (Date.now() - Date.parse(send.finished_at)) / 3600e3;
  const excerpt = String(item.title_youtube || item.caption_instagram || '(sin texto)').replace(/\s+/g, ' ').slice(0, 80);
  const now = new Date().toISOString();
  try {
    if (ageH >= STALL_H) {
      // Condicional al estado: si alguien decidió mientras tanto no se pisa
      const rows = await req('PATCH', 'content_items', { qs: { id: `eq.${item.id}`, status: 'eq.ready_for_review' }, body: { status: 'stalled' }, prefer: 'return=representation' });
      if (!rows.length) continue;
      await req('POST', 'pipeline_steps', { qs: { on_conflict: 'content_item_id,step,attempt' }, prefer: 'resolution=ignore-duplicates,return=minimal',
        body: { content_item_id: item.id, step: 'review_stalled', attempt: send.attempt, status: 'succeeded', started_at: now, finished_at: now } });
      out.stalled++;
      try {
        await tg('sendMessage', { chat_id, text: `⏸️ Pieza detenida: lleva ${Math.floor(ageH)} h sin decisión.\n«${excerpt}»\nSi sigue vigente, reábrela y te reenvío la propuesta.`,
          reply_markup: { inline_keyboard: [[{ text: '🔓 Reabrir', callback_data: `reopen_${item.id}` }, { text: '❌ Descartar', callback_data: `discard_${item.id}` }]] } });
      } catch (err) { await logError(item.id, 'telegram_http', err); }
    } else if (ageH >= REMIND_H) {
      // La fila reclama el recordatorio: la restricción única (item, paso, intento) evita repetirlo aunque el cron se solape
      const claim = await req('POST', 'pipeline_steps', { qs: { on_conflict: 'content_item_id,step,attempt' }, prefer: 'resolution=ignore-duplicates,return=representation',
        body: { content_item_id: item.id, step: 'review_reminder', attempt: send.attempt, status: 'started', started_at: now } });
      if (!claim.length) continue;
      try {
        await tg('sendMessage', { chat_id, text: `⏰ Recordatorio: esta pieza lleva ${Math.floor(ageH)} h esperando revisión.\n«${excerpt}»\nBusca su propuesta en el chat y apruébala, edítala, objétala o descártala. A las ${STALL_H} h se detiene.` });
        await req('PATCH', 'pipeline_steps', { qs: { content_item_id: `eq.${item.id}`, step: 'eq.review_reminder', attempt: `eq.${send.attempt}` }, body: { status: 'succeeded', finished_at: new Date().toISOString() } });
        out.reminded++;
      } catch (err) {
        // Se libera el reclamo para reintentar en la siguiente vuelta
        await req('DELETE', 'pipeline_steps', { qs: { content_item_id: `eq.${item.id}`, step: 'eq.review_reminder', attempt: `eq.${send.attempt}` } });
        await logError(item.id, 'telegram_http', err);
      }
    }
  } catch (err) { await logError(item.id, 'review_deadlines', err); }
}
return [{ json: out }];
